const isGithubUrl = (url: URL) => url.hostname === 'github.com'
const isTwitterUrl = (url: URL) =>
  url.hostname === 'twitter.com' || url.hostname === 'x.com'
const isTelegramUrl = (url: URL) => url.hostname === 't.me'
const isBilibiliUrl = (url: URL) => url.hostname.includes('bilibili.com')
const isZhihuUrl = (url: URL) => url.hostname === 'www.zhihu.com'
const isWikipediaUrl = (url: URL) => url.hostname.includes('wikipedia.org')
const isTMDBUrl = (url: URL) => url.hostname.includes('themoviedb.org')
const isMozillaUrl = (url: URL) => url.hostname.includes('mozilla.org')
const isNpmUrl = (url: URL) => url.hostname.includes('npmjs.com')
const isFigmaUrl = (url: URL) => url.hostname.includes('figma.com')
const isXiaoHongShuUrl = (url: URL) => url.hostname.includes('xiaohongshu.com')

const platformMap = [
  {
    type: 'GH',
    icon: <GitHubBrandIcon className="text-[#1D2127] dark:text-[#FFFFFF]" />,
    test: isGithubUrl,
  },
  { type: 'TW', icon: <TwitterIcon />, test: isTwitterUrl },
  {
    type: 'TG',
    icon: <TelegramIcon className="text-[#2AABEE]" />,
    test: isTelegramUrl,
  },
  {
    type: 'BL',
    icon: <BilibiliIcon className="text-[#469ECF]" />,
    test: isBilibiliUrl,
  },
  {
    type: 'ZH',
    icon: <ZhihuIcon className="text-[#0084FF]" />,
    test: isZhihuUrl,
  },
  {
    type: 'WI',
    icon: <WikipediaIcon className="text-current" />,
    test: isWikipediaUrl,
  },
  {
    type: 'TMDB',
    icon: <TheMovieDBIcon className="text-[#0D243F] dark:text-[#5CB7D2]" />,
    test: isTMDBUrl,
  },
  {
    type: 'Moz',
    icon: <MozillaIcon className="text-[#8cb4ff]" />,
    test: isMozillaUrl,
  },
  { type: 'Npm', icon: <NpmIcon />, test: isNpmUrl },
  {
    type: 'Figma',
    icon: <FigmaIcon className="text-[#A259FF]" />,
    test: isFigmaUrl,
  },
  {
    type: 'XHS',
    icon: <XiaoHongShuIcon className="text-[#FE2442]" />,
    test: isXiaoHongShuUrl,
  },
] as const

export type PlatformType = (typeof platformMap)[number]['type']

export const platformIconMap = Object.fromEntries(
  platformMap.map((item) => [item.type, item.icon]),
) as Record<PlatformType, ReactNode>

export function getPlatformFromUrl(url: URL): PlatformType | null {
  return platformMap.find((item) => item.test(url))?.type ?? null
}
